package crypto_test

import (
	"bytes"
	"crypto/hkdf"
	"crypto/mldsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/binary"
	"encoding/hex"
	"encoding/json/v2"
	"os"
	"strings"
	"testing"

	"github.com/Hikyo-Org/hikyo/internal/crypto"
)

// Frozen interoperability vectors for the transit ML-DSA-65 key
// (post-quantum migration DEC-09). The file was produced once by a stdlib-only
// program (crypto/hkdf and crypto/mldsa) and is never regenerated by the code
// under test. The first test below imports nothing from the transit code path:
// it re-derives the seed, public key and verification from the stdlib alone, so
// a bug that changes both sides of the transit code cannot hide.

type mldsaVectors struct {
	Material         string `json:"material_hex"`
	HKDFInfo         string `json:"hkdf_info_hex"`
	Seed             string `json:"seed_hex"`
	PublicKey        string `json:"public_key_hex"`
	PublicKeySHA256  string `json:"public_key_sha256"`
	Context          string `json:"context"`
	Message          string `json:"message"`
	Signature        string `json:"signature_hex"`
	PayloadWire      string `json:"payload_wire"`
	EmptyContextSign string `json:"empty_context_signature_hex"`
	PublicKeySPKI    string `json:"public_key_spki_hex"`
}

func loadMLDSAVectors(t *testing.T) mldsaVectors {
	t.Helper()
	raw, err := os.ReadFile("testdata/transit_mldsa65_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v mldsaVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// An independent verifier needs only the public key, the context string and the
// payload layout (two-byte identifier 0x0905, then the FIPS 204 signature).
func TestTransitMLDSA65VectorsVerifyWithTheStdlibAlone(t *testing.T) {
	v := loadMLDSAVectors(t)
	material, info := unhex(t, v.Material), unhex(t, v.HKDFInfo)

	seed, err := hkdf.Key(sha256.New, material, nil, string(info), 32)
	if err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(seed) != v.Seed {
		t.Fatal("seed derivation differs from the frozen vector")
	}
	sk, err := mldsa.NewPrivateKey(mldsa.MLDSA65(), seed)
	if err != nil {
		t.Fatal(err)
	}
	if got := hex.EncodeToString(sk.PublicKey().Bytes()); got != v.PublicKey {
		t.Fatal("public key differs from the frozen vector")
	}
	if sum := sha256.Sum256(unhex(t, v.PublicKey)); hex.EncodeToString(sum[:]) != v.PublicKeySHA256 {
		t.Fatal("frozen public key digest mismatch")
	}

	pk, err := mldsa.NewPublicKey(mldsa.MLDSA65(), unhex(t, v.PublicKey))
	if err != nil {
		t.Fatal(err)
	}
	// The frozen SPKI is the same key: the standard library parses it back.
	if parsed, err := x509.ParsePKIXPublicKey(unhex(t, v.PublicKeySPKI)); err != nil || !pk.Equal(parsed) {
		t.Fatalf("frozen SPKI is not the frozen key: %v", err)
	}
	sig := unhex(t, v.Signature)
	msg := []byte(v.Message)
	if err := mldsa.Verify(pk, msg, sig, &mldsa.Options{Context: v.Context}); err != nil {
		t.Fatalf("frozen signature does not verify: %v", err)
	}
	if mldsa.Verify(pk, []byte("tampered"), sig, &mldsa.Options{Context: v.Context}) == nil {
		t.Error("signature verified another message")
	}
	if mldsa.Verify(pk, msg, sig, &mldsa.Options{Context: ""}) == nil {
		t.Error("signature verified under the empty context: the label is not bound")
	}
	if mldsa.Verify(pk, msg, unhex(t, v.EmptyContextSign), &mldsa.Options{Context: v.Context}) == nil {
		t.Error("a signature made under another context verified under the transit label")
	}

	// The wire value is "hikyo:v3:" ‖ base64url(0x0905 ‖ signature).
	enc, ok := strings.CutPrefix(v.PayloadWire, "hikyo:v3:")
	if !ok {
		t.Fatal("wire prefix")
	}
	payload, err := base64.RawURLEncoding.Strict().DecodeString(enc)
	if err != nil {
		t.Fatal(err)
	}
	if binary.BigEndian.Uint16(payload) != 0x0905 || !bytes.Equal(payload[2:], sig) {
		t.Fatal("wire payload is not identifier ‖ signature")
	}
}

// The transit code path must agree with the independent derivation byte for
// byte, and must verify the frozen signature and refuse each substitution.
func TestTransitMLDSA65VectorsAgreeWithTheTransitCodePath(t *testing.T) {
	v := loadMLDSAVectors(t)
	k, err := crypto.OpenTransitKey(unhex(t, v.Material), crypto.TransitBinding{
		Algorithm: crypto.TransitMLDSA65, OrgID: "org_1", ProjectID: "prj_1", EnvID: "env_1", KeyID: "tk_1", Version: 3,
	})
	if err != nil {
		t.Fatal(err)
	}
	pub, err := k.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(pub) != v.PublicKey {
		t.Fatal("transit derivation differs from the independent one: the HKDF binding changed")
	}
	version, payload, err := crypto.ParseTransitValue(v.PayloadWire)
	if err != nil || version != 3 {
		t.Fatalf("frozen wire value refused: %d %v", version, err)
	}
	msg := []byte(v.Message)
	if !crypto.VerifyTransitSignature(crypto.TransitMLDSA65, pub, msg, payload) {
		t.Fatal("transit verify refused the frozen signature")
	}
	if crypto.VerifyTransitSignature(crypto.TransitMLDSA65, pub, []byte("tampered"), payload) {
		t.Error("another message verified")
	}
	// Wrong algorithm: the payload is not an Ed25519 signature, and the Ed25519
	// verifier cannot be selected by a presented ML-DSA payload.
	if crypto.VerifyTransitSignature(crypto.TransitEd25519, pub, msg, payload) {
		t.Error("ML-DSA payload verified under the ed25519 verifier")
	}
	// Signature substitution: the empty-context signature under the right
	// identifier is refused.
	sub := append([]byte{0x09, 0x05}, unhex(t, v.EmptyContextSign)...)
	if crypto.VerifyTransitSignature(crypto.TransitMLDSA65, pub, msg, sub) {
		t.Error("a signature under another context verified")
	}
	// A fresh (hedged) signature from the transit path verifies with the stdlib
	// alone and carries the identifier.
	fresh, err := k.Sign(msg)
	if err != nil {
		t.Fatal(err)
	}
	if len(fresh) != 3311 || binary.BigEndian.Uint16(fresh) != 0x0905 {
		t.Fatalf("payload shape: %d bytes", len(fresh))
	}
	pk, err := mldsa.NewPublicKey(mldsa.MLDSA65(), pub)
	if err != nil {
		t.Fatal(err)
	}
	if err := mldsa.Verify(pk, msg, fresh[2:], &mldsa.Options{Context: crypto.TransitMLDSASignContext}); err != nil {
		t.Fatalf("stdlib refused a transit signature: %v", err)
	}
	again, err := k.Sign(msg)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Equal(fresh, again) {
		t.Error("two signatures are identical: signing is not hedged")
	}
}

// The published form of an ML-DSA-65 public key is the standard SPKI (DEC-07),
// readable by stock tooling; Ed25519 stays raw. The frozen key is parsed back
// with the standard library alone and compared with the stored raw encoding.
func TestExposeTransitPublicKey(t *testing.T) {
	v := loadMLDSAVectors(t)
	raw := unhex(t, v.PublicKey)
	der, err := crypto.ExposeTransitPublicKey(crypto.TransitMLDSA65, raw)
	if err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(der) != v.PublicKeySPKI {
		t.Fatal("published SPKI differs from the frozen vector")
	}
	if len(der) != 1974 || !bytes.Contains(der, []byte{0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x03, 0x12}) {
		t.Fatalf("SPKI is %d bytes or lacks the ML-DSA-65 OID 2.16.840.1.101.3.4.3.18", len(der))
	}
	parsed, err := x509.ParsePKIXPublicKey(der)
	if err != nil {
		t.Fatal(err)
	}
	pk, ok := parsed.(*mldsa.PublicKey)
	if !ok || !bytes.Equal(pk.Bytes(), raw) || pk.Parameters() != mldsa.MLDSA65() {
		t.Fatal("published SPKI does not parse back to the stored ML-DSA-65 key")
	}
	edRaw := make([]byte, 32)
	if got, err := crypto.ExposeTransitPublicKey(crypto.TransitEd25519, edRaw); err != nil || !bytes.Equal(got, edRaw) {
		t.Fatalf("ed25519 public key changed: %v", err)
	}
	for name, c := range map[string]struct {
		alg    crypto.TransitAlgorithm
		stored []byte
	}{
		"short ml-dsa":    {crypto.TransitMLDSA65, raw[:1951]},
		"ed25519 as pq":   {crypto.TransitMLDSA65, edRaw},
		"long ed25519":    {crypto.TransitEd25519, raw},
		"hmac":            {crypto.TransitHMACSHA256, edRaw},
		"empty algorithm": {"", edRaw},
	} {
		if _, err := crypto.ExposeTransitPublicKey(c.alg, c.stored); err == nil {
			t.Errorf("%s: accepted", name)
		}
	}
}
